statement:
\begin{enumerate}
\item[(a)] Given any positive integer $n$, show that there exist distinct positive integers $x$ and $y$ such that $x + j$ divides $y + j$ for $j = 1, 2, 3, \ldots, n$.
\item[(b)] If for some positive integers $x$ and $y$, $x + j$ divides $y + j$ for all positive integers $j$, prove that $x = y$.
\end{enumerate}
